/// The gallery's example of `AudioPlayerButton`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_transcript = args.text("transcript");
        let arg_loading = args.bool("loading");

        // A second of a low tone, computed here. An app delivers its own recording.
        let tone: Vec<f32> =
            (0..44_100).map(|i| (i as f32 / 44_100.0 * 220.0 * std::f32::consts::TAU).sin() * 0.2).collect();
        {
            let mut it = AudioPlayerButton::new().clip(SoundClip::new(tone, 44_100));
            it = it.transcript(arg_transcript.clone());
            it = it.loading(arg_loading);
            it
        }
        .width(320.0)
    })
}

impl ComponentBook for AudioPlayerButton {
    fn book() -> Meta {
        Meta::new("Forms/AudioPlayerButton", render)
            .summary("Plays and stops a recording, with progress and a transcript to open.")
            .arg(ArgType::text("transcript", "What was said goes here, to open when wanted."))
            .arg(ArgType::bool("loading", false))
            .story("Example", Args::new())
            .story("Loading", Args::new().with("loading", true))
    }
}
